def copy_room_limits(apps, schema_editor):
    """Los juegos existentes toman los límites reales de sus salas activas."""
    Game = apps.get_model("roulette", "Game")
    alias = schema_editor.connection.alias
    for game in Game.objects.using(alias).all():
        limits = game.rooms.filter(is_active=True).aggregate(low=Min("min_bet"), high=Max("max_bet"))
        if limits["low"] is not None:
            game.min_bet, game.max_bet = limits["low"], limits["high"]
            game.save(update_fields=["min_bet", "max_bet"])


